import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* input, const float* weight, float* output,
    int batch_size, int channels,
    int in_height, int in_width,
    int kernel_size, int stride, int padding,
    int out_height, int out_width) {

    int n = blockIdx.z;
    int c = blockIdx.y;
    int h_out = blockIdx.x * blockDim.y + threadIdx.y;
    int w_out = threadIdx.x;

    if (n >= batch_size || c >= channels || h_out >= out_height || w_out >= out_width) return;

    float sum = 0.0f;
    int h_in_start = h_out * stride - padding;
    int w_in_start = w_out * stride - padding;

    #pragma unroll
    for(int kh = 0; kh < 3; kh++) {
        int h_in = h_in_start + kh;
        if(h_in < 0 || h_in >= in_height) continue;

        #pragma unroll
        for(int kw = 0; kw < 3; kw++) {
            int w_in = w_in_start + kw;
            if(w_in < 0 || w_in >= in_width) continue;

            sum += input[n*channels*in_height*in_width + c*in_height*in_width + 
                        h_in*in_width + w_in] * 
                   weight[c*9 + kh*3 + kw];
        }
    }

    output[n*channels*out_height*out_width + c*out_height*out_width + 
          h_out*out_width + w_out] = sum;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input, torch::Tensor weight,
    int kernel_size, int stride, int padding) {

    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_h = (in_h + 2*padding - kernel_size)/stride + 1;
    int out_w = (in_w + 2*padding - kernel_size)/stride + 1;

    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());

    dim3 threads(32, 8);
    dim3 blocks((out_h + threads.y-1)/threads.y, channels, batch_size);

    depthwise_conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels,
        in_h, in_w,
        3, stride, padding,
        out_h, out_w
    );

    return output;
}
"""

depthwise_conv2d_cpp_source = "torch::Tensor depthwise_conv2d_cuda(torch::Tensor input, torch::Tensor weight, int kernel_size, int stride, int padding);"

depthwise_conv2d = load_inline(
    name='depthwise_conv2d',
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=['depthwise_conv2d_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super().__init__()
        if in_channels != out_channels:
            raise ValueError("Depthwise conv requires in_channels == out_channels")

        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

        self.weight = nn.Parameter(torch.Tensor(out_channels, 1, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.bias = None

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = depthwise_conv2d.depthwise_conv2d_cuda(
            x, self.weight, 
            self.kernel_size, self.stride, self.padding
        )
        if self.bias is not None:
            x += self.bias.view(1, -1, 1, 1)
        return x
